def mean_absolute_deviation(numbers: List[float]) -> float:
    n = len(numbers)
    if n <= 1:
        return 0.0
    mean, mad = sum(numbers) / float(n), 0.0
    for x in numbers:
        mad = max(mad, abs(x - mean))
    return mad / float(n)
```

