def parse_nested_parens(paren_string):
    max_depth = 0
    depth = 0
    result = []
    for paren in paren_string.split(' '):
        for paren in paren.split('('):
            depth += 1
            if depth > max_depth:
                max_depth = depth
        for paren in paren.split(')'):
            depth -= 1
        result.append(max_depth)
    return result
```

