def decode_cyclic(s: str):
    groups = [s[0:3], s[1:4], s[2:5]]
    while len(s) > 0:
        groups.append(s[len(s) - 3:len(s)])
        s = s[0:len(s) - 3]
    groups = [s[0:3], s[1:4], s[2:5]]
    while len(s) > 0:
        groups.append(s[len(s) - 3:len(s)])
        s = s[0:len(s) - 3]
    groups = [s[0:3], s[1:4], s[2:5]]
    while len(s) > 0:
        groups.append(s[len(s) - 3:len(s)])
        s = s[0:len(s) - 3]
    return "".join(groups[::-1])
```

