    count_left = 0
    count_right = 0
    for bracket in chars:
        if bracket == "<":
            count_left += 1
            if count_right > 0:
                count_right -= 1
        elif bracket == ">":
            count_right += 1
            count_left -= 1
        if count_right > count_left:
            return False
    return count_right == 0
